mapper.select:
select t.create_time,t.create_time createTime,t.calling_type,t.calling_type
callingType,t.remark,t.status_cd,t.status_cd statusCd,t.platform_id,t.platform_id
platformId,t.community_id,t.community_id communityId,t.device_id,t.device_id
deviceId,t.device_name,t.device_name deviceName,t.calling_num,t.calling_num callingNum,cp.platform_name platformName
from calling_device t
left join calling_platform cp on t.platform_id = cp.platform_id and cp.status_cd = '0'
where 1 =1

    and t.create_time= #{createTime}


    and t.calling_type= #{callingType}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.platform_id= #{platformId}


    and t.community_id= #{communityId}


    and t.device_id= #{deviceId}


    and t.device_name= #{deviceName}


    and t.calling_num= #{callingNum}

order by t.create_time desc

    limit #{page}, #{row}

mapper.update:
update calling_device t set t.status_cd = #{statusCd}

    , t.create_time= #{createTime}


    , t.calling_type= #{callingType}


    , t.remark= #{remark}


    , t.platform_id= #{platformId}


    , t.community_id= #{communityId}



    , t.device_name= #{deviceName}


    , t.calling_num= #{callingNum}

where 1=1

    and t.device_id= #{deviceId}

mapper.select:
select count(1) count
from calling_device t
where 1 =1

    and t.create_time= #{createTime}


    and t.calling_type= #{callingType}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.platform_id= #{platformId}


    and t.community_id= #{communityId}


    and t.device_id= #{deviceId}


    and t.device_name= #{deviceName}


    and t.calling_num= #{callingNum}
